 15→)
 16→
 17→// statusStyles holds pre-built lipgloss styles and terminal metadata.
 18→type statusStyles struct {
 19→	colorEnabled bool
 20→	width        int
 21→
 22→	// Styles
 23→	green lipgloss.Style
 24→	red   lipgloss.Style
 25→	gray  lipgloss.Style
 26→	bold  lipgloss.Style
 27→	dim   lipgloss.Style
 28→	agent lipgloss.Style // amber/orange for agent names
 29→	cyan  lipgloss.Style
 30→}
 31→
 32→// newStatusStyles creates styles appropriate for the output writer.
 33→func newStatusStyles(w io.Writer) statusStyles {
 34→	useColor := shouldUseColor(w)
 35→	width := getTerminalWidth(w)
 36→
 37→	s := statusStyles{
 38→		colorEnabled: useColor,
 39→		width:        width,
 40→	}
 41→
 42→	if useColor {
 43→		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
 44→		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
 45→		s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
 46→		s.bold = lipgloss.NewStyle().Bold(true)
 47→		s.dim = lipgloss.NewStyle().Faint(true)
 48→		s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
 49→		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
 50→	}
 51→
 52→	return s
 53→}
 54→
 55→// render applies a style to text only when color is enabled.
 56→func (s statusStyles) render(style lipgloss.Style, text string) string {
 57→	if !s.colorEnabled {
 58→		return text
 59→	}
 60→	return style.Render(text)
 61→}
 62→
 63→// isTerminalWriter returns true if the writer is connected to a terminal.
 64→func isTerminalWriter(w io.Writer) bool {
 65→	if f, ok := w.(*os.File); ok {
 66→		return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
 67→	}
 68→	return false
 69→}
 70→
 71→// shouldUseColor returns true if the writer supports color output.
 72→func shouldUseColor(w io.Writer) bool {
 73→	if os.Getenv("NO_COLOR") != "" {
 74→		return false
 75→	}
 76→	return isTerminalWriter(w)
 77→}
 78→
 79→// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
 80→// It first checks the writer itself, then falls back to Stdout/Stderr.
 81→func getTerminalWidth(w io.Writer) int {
 82→	// Try the output writer first
 83→	if f, ok := w.(*os.File); ok {
 84→		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
 85→			return min(width, 80)
 86→		}
 87→	}
 88→
 89→	// Fall back to Stdout, then Stderr
 90→	for _, f := range []*os.File{os.Stdout, os.Stderr} {
 91→		if f == nil {
 92→			continue
 93→		}
 94→		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
 95→			return min(width, 80)
 96→		}
 97→	}
 98→
 99→	return 60
100→}
101→
102→// formatTokenCount formats a token count for display.
103→// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
104→func formatTokenCount(n int) string {
105→	if n < 1000 {
106→		return strconv.Itoa(n)
107→	}
108→	f := float64(n) / 1000.0
109→	s := fmt.Sprintf("%.1f", f)
110→	// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
111→	s = strings.TrimSuffix(s, ".0")
112→	return s + "k"
113→}
114→
115→// totalTokens recursively sums all token fields including subagent tokens.
116→func totalTokens(tu *agent.TokenUsage) int {
117→	if tu == nil {
118→		return 0
119→	}
120→	total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
121→	total += totalTokens(tu.SubagentTokens)
122→	return total
123→}
124→
125→// horizontalRule renders a dimmed horizontal rule of the given width.
126→func (s statusStyles) horizontalRule(width int) string {
127→	rule := strings.Repeat("─", width)
128→	return s.render(s.dim, rule)
129→}
130→
131→// sectionRule renders a section header like: ── Active Sessions ────────────
132→func (s statusStyles) sectionRule(label string, width int) string {
133→	prefix := "── "
134→	content := label + " "
135→	usedWidth := len([]rune(prefix)) + len([]rune(content))
136→	trailing := width - usedWidth
137→	if trailing < 1 {
138→		trailing = 1
139→	}
140→
141→	var b strings.Builder
142→	b.WriteString(s.render(s.dim, "── "))
143→	b.WriteString(s.render(s.dim, label))
144→	b.WriteString(" ")
145→	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
146→	return b.String()
147→}
148→
149→// activeTimeDisplay formats a last interaction time for display.
150→// Returns "active now" for recent activity (<1min), otherwise "active Xm ago".
151→func activeTimeDisplay(lastInteraction *time.Time) string {
152→	if lastInteraction == nil {
153→		return ""
154→	}
155→	d := time.Since(*lastInteraction)
156→	if d < time.Minute {
157→		return "active now"
158→	}
159→	return "active " + timeAgo(*lastInteraction)
160→}
