 25→func newStatusCmd() *cobra.Command {
 26→	var detailed bool
 27→
 28→	cmd := &cobra.Command{
 29→		Use:   "status",
 30→		Short: "Show Entire status",
 31→		Long:  "Show whether Entire is currently enabled or disabled",
 32→		RunE: func(cmd *cobra.Command, _ []string) error {
 33→			return runStatus(cmd.Context(), cmd.OutOrStdout(), detailed)
 34→		},
 35→	}
 36→
 37→	cmd.Flags().BoolVar(&detailed, "detailed", false, "Show detailed status for each settings file")
 38→
 39→	return cmd
 40→}
