135→// formatSettingsStatusShort formats a short settings status line.
136→// Output format: "● Enabled · manual-commit · branch main" or "○ Disabled"
137→func formatSettingsStatusShort(ctx context.Context, s *EntireSettings, sty statusStyles) string {
138→	displayName := strategy.StrategyNameManualCommit
139→
140→	var b strings.Builder
141→
142→	if s.Enabled {
143→		b.WriteString(sty.render(sty.green, "●"))
144→		b.WriteString(" ")
145→		b.WriteString(sty.render(sty.bold, "Enabled"))
146→	} else {
147→		b.WriteString(sty.render(sty.red, "○"))
148→		b.WriteString(" ")
149→		b.WriteString(sty.render(sty.bold, "Disabled"))
150→	}
151→
152→	b.WriteString(sty.render(sty.dim, " · "))
153→	b.WriteString(displayName)
154→
155→	// Resolve branch from repo root
156→	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
157→		if branch := resolveWorktreeBranch(ctx, repoRoot); branch != "" {
158→			b.WriteString(sty.render(sty.dim, " · "))
159→			b.WriteString("branch ")
160→			b.WriteString(sty.render(sty.cyan, branch))
161→		}
162→	}
163→
164→	return b.String()
165→}
