167→// formatSettingsStatus formats a settings status line with source prefix.
168→// Output format: "Project · enabled · manual-commit" or "Local · disabled"
169→func formatSettingsStatus(prefix string, s *EntireSettings, sty statusStyles) string {
170→	displayName := strategy.StrategyNameManualCommit
171→
172→	var b strings.Builder
173→	b.WriteString(sty.render(sty.bold, prefix))
174→	b.WriteString(sty.render(sty.dim, " · "))
175→
176→	if s.Enabled {
177→		b.WriteString("enabled")
178→	} else {
179→		b.WriteString("disabled")
180→	}
181→
182→	b.WriteString(sty.render(sty.dim, " · "))
183→	b.WriteString(displayName)
184→
185→	return b.String()
186→}
