 45→func TestResolveWorktreeBranch_DetachedHEAD(t *testing.T) {
 46→	dir := t.TempDir()
 47→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 48→		dir = resolved
 49→	}
 50→
 51→	repo, err := git.PlainInit(dir, false)
 52→	if err != nil {
 53→		t.Fatalf("git init: %v", err)
 54→	}
 55→
 56→	// Create a commit so we can detach HEAD
